package com.sentinelcore.assetservice.controller; import java.util.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import com.sentinelcore.assetservice.dto.ComplianceSummaryResponse; import com.sentinelcore.assetservice.entity.*; import com.sentinelcore.assetservice.service.ComplianceService;
@RestController @RequestMapping("/api/compliance") public class ComplianceController { private final ComplianceService service; public ComplianceController(ComplianceService s){service=s;} @GetMapping("/frameworks") public ResponseEntity<List<ComplianceFramework>> frameworks(){return ResponseEntity.ok(service.frameworks());} @GetMapping("/controls") public ResponseEntity<List<ComplianceControl>> controls(@RequestParam(required=false) UUID frameworkId){return ResponseEntity.ok(service.controls(frameworkId));} @GetMapping("/summary/{frameworkId}") public ResponseEntity<ComplianceSummaryResponse> summary(@PathVariable UUID frameworkId){return ResponseEntity.ok(service.summary(frameworkId));} }